<li><b>\u770b\u6c34\u9762</b>\uff1a\u6240\u6709\u6c34\u9762\u4e00\u8d77\u53d8\u4eae\u3001\u9646\u5730\u4e0d\u53d8\uff1f\u2192 \u8000\u6591\u3002</li>
<li><b>\u770b\u8fb9\u7f18</b>\uff1a\u9053\u8def\u3001\u7530\u57c2\u3001\u6cb3\u5cb8\u4e00\u5708\u6210\u5bf9\u7ec6\u6761\u5e26\uff1f\u2192 \u9519\u4f4d\u3002</li>
<li><b>\u770b\u5761\u5411</b>\uff1a\u53d8\u5316\u53ea\u51fa\u73b0\u5728\u67d0\u4e00\u4fa7\u7684\u5761\u4e0a\uff0c\u4e14\u5b63\u8282\u4e0d\u540c\uff1f\u2192 \u5730\u5f62\u9634\u5f71\u3002</li>
